export const k8sActivityCommand = defineCommand({
  description: 'List the recent activity of a Kubernetes cluster',
  since: null,
  options: {
    org: orgaIdOrNameOption,
    limit: defineOption({
      name: 'limit',
      schema: z.coerce.number().int().min(1).optional(),
      description: 'Maximum number of events to show',
      placeholder: 'limit',
    }),
    format: humanJsonOutputFormatOption,
  },
  args: [k8sIdOrNameArg],
  async handler(options, clusterIdOrName) {
    const { format, org: orgIdOrName, limit } = options;

    const events = await k8sListActivity(orgIdOrName, clusterIdOrName, limit);

    switch (format) {
      case 'json':
        Logger.printJson(events);
        break;
      case 'human':
      default:
        if (events.length === 0) {
          Logger.println('🔎 No activity found for this cluster');
          return;
        }

        console.table(
          events.map((event) => ({
            Date: event.createdAt ?? event.date ?? '-',
            Event: event.type ?? event.event ?? '-',
            Status: event.status ?? event.state ?? '-',
            Message: event.message ?? event.description ?? '-',
          })),
        );
        break;
    }
  },
});
